3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Validates that a telephone number can be converted to a canonical E.164 form.
10	 * The check delegates to {@link Owner#normalizeTelephone(String)}, the single
11	 * source of truth for how a telephone is normalized before it is persisted, so
12	 * the validated input and the stored value agree on validity.
13	 */
